APPROVED_EDITS.setdefault('SITE_ARCHITECTURE.md',[]).extend([('- Add a new section by adding a real linked card to the homepage directory; the grid wraps to additional rows.\n', '- Add a new section by adding a real linked card to the homepage directory; the grid wraps to additional rows.\n- `/tools/` "Find the right tool." directory and its search read one data source, `tools/catalog.js`: calculators in `PT_CATS`, guides and the checkup in `PT_GUIDES`, topics in `PT_TOPICS`. When the daily build adds a tool or guide, add it there (with plain-English `kw` keywords and at least one topic), add the same link to the `<noscript>` list in `tools/index.html`, add it to `tools/sitemap.xml` and `tools/llms.txt`, then bump the `?v=` tokens on `catalog.js` and `v7/home.js`. `tests/find-right-tool.cjs` fails if any sitemap page is missing from the data, the directory, its search or the no-JavaScript list.\n')])
def show(ref,name):
 return subprocess.check_output(['git','show',ref+':'+name],cwd=ROOT)
def reviewed(name):
 """Bytes of name at REVIEWED with only this PR's exact approved edits applied."""
 data=show(REVIEWED,name)
 if name not in APPROVED_EDITS:return data
 data=data.decode()
 for old,new in APPROVED_EDITS.get(name,[]):
  assert data.count(old)==1,(name,old)
  data=data.replace(old,new)
 return data.encode()
