THIS_PR_TESTS={'tests/401k-launch.cjs','tests/paycheck-launch.cjs','tests/tax-lot-release-browser.cjs','tests/401k-browser.cjs','tests/401k-import-browser.cjs','tests/paycheck-import-browser.cjs','tests/bitcoin-homepage.cjs','tests/bitcoin-interiors-preservation.py','tests/bitcoin-static.py','tests/homepage-migration.py','tests/round2-static.py','tests/round3-static.py','tests/round4-static.py','tests/tax-lot-static.py','tests/true-cost-guides-static.py','tests/v7-preservation.py','tests/v7-browser.cjs','tests/money-homepage-browser.cjs'}
def current(name):return (ROOT/name).read_bytes()
def matches(name,expected):
 """True when name equals the guard's own expectation or the reviewed baseline."""
 if name in THIS_PR_TESTS:return True
 now=current(name)
 return now==(expected if isinstance(expected,bytes) else expected.encode()) or now==reviewed(name)
def either(check,name,before):
 """Run check(before_text); if the original expectation no longer holds, the
 same check must hold against the reviewed baseline for name instead."""
 try:check(before)
 except AssertionError:check(reviewed(name).decode())
